(() => {
  'use strict';

  const payload = '';

  const fail = (message) => {
    document.body.innerHTML = `<main style="font:16px/1.5 system-ui,sans-serif;padding:40px;max-width:760px;margin:auto"><h1>DATA</h1><p>${message}</p></main>`;
  };

  const boot = async () => {
    if (!('DecompressionStream' in window)) {
      fail('Este navegador não oferece suporte ao carregamento desta versão de DATA.');
      return;
    }

    const bytes = Uint8Array.from(atob(payload), (c) => c.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
    const html = await new Response(stream).text();
    document.open();
    document.write(html);
    document.close();
  };

  boot().catch((error) => {
    console.error('[DATA bootstrap]', error);
    fail('Não foi possível carregar DATA.');
  });
})();
